using mmr::require;
namespace fs=std::filesystem;
constexpr double NaN=std::numeric_limits<double>::quiet_NaN();
const std::array<std::string,3> names={"data","mc_old_threshold","mc_new_threshold_MPVwoCT"};
struct Row {int sample=0,run=0,event=0,time=0,id=0,observed=0,ambiguous=0,calib=0,response=0;double hg=NaN,saved=NaN,T=NaN,sx=NaN,sy=NaN,length=NaN,longAt=NaN,transAt=NaN,truth=NaN;};
using Key=std::tuple<int,int,int,int,int,int>;
Key key(const Row&r){return {r.run,r.id,int(std::floor(r.longAt/5)),int(std::floor(r.transAt/1.5)),int(std::floor(r.sx/.01)),int(std::floor(r.sy/.01))};}
int group(int id,const mmr::Parameter&p){return (mmr::group(id)?0:2)+int(p.mipFallback);}
std::string groupName(int g){return std::string(g<2?"10um":"15um")+(g%2?"_fallback":"_individual");}
bool eligible(const Row&r){return r.response&&r.observed&&!r.ambiguous&&r.calib&&std::isfinite(r.hg)&&r.hg<2600&&std::isfinite(r.length)&&r.length>0&&std::isfinite(r.T)&&mmr::tempFactor(r.id,r.T)>0;}
std::vector<Row> load(const fs::path&path,int which){auto f=mmr::openFile(path.string());auto*t=mmr::tree(*f,"Crossings");Row r;mmr::bind(t,"sample",&r.sample);mmr::bind(t,"run",&r.run);mmr::bind(t,"event",&r.event);mmr::bind(t,"event_time",&r.time);mmr::bind(t,"cellid",&r.id);mmr::bind(t,"observed",&r.observed);mmr::bind(t,"ambiguous",&r.ambiguous);mmr::bind(t,"calib_ok",&r.calib);mmr::bind(t,"response_ok",&r.response);mmr::bind(t,"raw_hg",&r.hg);mmr::bind(t,"saved_hg",&r.saved);mmr::bind(t,"temperature",&r.T);mmr::bind(t,"sx",&r.sx);mmr::bind(t,"sy",&r.sy);mmr::bind(t,"length",&r.length);mmr::bind(t,"longitudinal",&r.longAt);mmr::bind(t,"transverse",&r.transAt);mmr::bind(t,"truth_edep",&r.truth);std::vector<Row>rows;for(Long64_t i=0;i<t->GetEntries();++i){mmr::read(t,i);if(r.sample==which)rows.push_back(r);}t->ResetBranchAddresses();return rows;}
struct Summary {double sw=0,sw2=0,sx=0,sx2=0;long long n=0;std::map<std::pair<int,int>,std::pair<double,double>>events;void add(const Row&r,double v,double w){if(!(w>0)||!std::isfinite(v))return;++n;sw+=w;sw2+=w*w;sx+=w*v;sx2+=w*v*v;auto&a=events[{r.time,r.event}];a.first+=w*v;a.second+=w;}double mean()const{return sw>0?sx/sw:NaN;}double neff()const{return sw2>0?sw*sw/sw2:0;}double error()const{if(events.size()<2||!sw)return NaN;double variance=0,m=mean();for(auto&a:events)variance+=std::pow(a.second.first-m*a.second.second,2);return std::sqrt(variance*events.size()/(events.size()-1))/sw;}};
struct Efficiency {Summary observed,response;};
std::unique_ptr<TH1D> hist(const std::string&name,const std::string&title,int n=200,double low=0,double high=8){auto h=std::make_unique<TH1D>(name.c_str(),title.c_str(),n,low,high);h->SetDirectory(nullptr);h->Sumw2();return h;}
struct Spectrum {std::unique_ptr<TH1D>h;Summary stats;double maxFactor=0,minFactor=1e30;};
struct Fit {bool valid=false;std::string status="insufficient_hits";double mpv=NaN,error=NaN,landau=NaN,gaussian=NaN,chi=NaN,low=NaN,high=NaN,area=NaN;int root=-999,cov=-1;};
double langau(double*x,double*p){const double shift=-.22278298,inv=.3989422804014327;double center=p[1]-shift*p[0],a=x[0]-5*p[3],b=x[0]+5*p[3],step=(b-a)/60,sum=0;for(int i=0;i<60;++i){double z=a+(i+.5)*step;sum+=TMath::Landau(z,center,p[0],false)/p[0]*TMath::Gaus(x[0],z,p[3],false);}return p[2]*step*sum*inv/p[3];}
Fit fit(const TH1D&h,double low,double high){Fit r;r.low=std::max(.02,low);r.high=std::min(7.98,high);if(r.high-r.low<12*h.GetBinWidth(1)){r.status="plateau_range_too_short";return r;}int first=h.FindFixBin(r.low),last=h.FindFixBin(r.high),peak=first;double sw=0,sw2=0;for(int b=first;b<=last;++b){sw+=h.GetBinContent(b);sw2+=std::pow(h.GetBinError(b),2);if(h.GetBinContent(b)>h.GetBinContent(peak))peak=b;}if(!(sw2>0)||sw*sw/sw2<100)return r;TF1 f("ct_langau",langau,r.low,r.high,4);double area=std::max(sw*h.GetBinWidth(1),.001);f.SetParameters(.12,std::clamp(h.GetBinCenter(peak),r.low+.08,r.high-.08),area,.08);f.SetParLimits(0,.005,1);f.SetParLimits(1,r.low,r.high);f.SetParLimits(2,.001*area,100*area);f.SetParLimits(3,.003,1.5);auto copy=std::unique_ptr<TH1D>(static_cast<TH1D*>(h.Clone("ct_fit_work")));copy->SetDirectory(nullptr);auto result=copy->Fit(&f,"QRS0N");r.root=int(result);r.cov=result.Get()?result->CovMatrixStatus():-1;r.mpv=f.GetParameter(1);r.error=f.GetParError(1);r.landau=f.GetParameter(0);r.gaussian=f.GetParameter(3);r.area=f.GetParameter(2);r.chi=f.GetNDF()>0?f.GetChisquare()/f.GetNDF():NaN;r.status="fit_failed";if(r.root)return r;r.status="poor_covariance";if(r.cov<2)return r;r.status="poor_chi2";if(!std::isfinite(r.chi)||r.chi>3)return r;r.status="invalid_mpv";if(!std::isfinite(r.mpv)||r.mpv<=0||!std::isfinite(r.error)||r.error<=0)return r;r.status="mpv_boundary";if(r.mpv<=r.low+.08||r.mpv>=r.high-.08)return r;for(int p=0;p<4;++p){double lo,hi;f.GetParLimits(p,lo,hi);if(f.GetParameter(p)-lo<.001*(hi-lo)||hi-f.GetParameter(p)<.001*(hi-lo)){r.status="parameter_boundary";return r;}}r.status="ok";r.valid=true;return r;}
double quantile(const TH1D&h,double p){double total=h.Integral(1,h.GetNbinsX()),sum=0;if(!total)return NaN;for(int b=1;b<=h.GetNbinsX();++b){double v=h.GetBinContent(b);if(sum+v>=p*total&&v>0)return h.GetBinLowEdge(b)+(p*total-sum)/v*h.GetBinWidth(b);sum+=v;}return h.GetXaxis()->GetXmax();}
double median(std::vector<double>v){if(v.empty())return NaN;std::sort(v.begin(),v.end());return v.size()%2?v[v.size()/2]:.5*(v[v.size()/2-1]+v[v.size()/2]);}
std::pair<double,double> medianCI(const std::vector<double>&v){if(v.size()<3)return {NaN,NaN};std::mt19937 rng(20261013);std::vector<double>m;for(int b=0;b<1000;++b){std::vector<double>x;for(size_t i=0;i<v.size();++i)x.push_back(v[rng()%v.size()]);m.push_back(median(x));}std::sort(m.begin(),m.end());return {m[25],m[974]};}
void draw(TCanvas&c,int pad,const std::array<Spectrum,3>&sp,const std::string&title,std::vector<std::unique_ptr<TH1D>>&clones){c.cd(pad);bool first=true;TLegend legend(.55,.70,.9,.89);const std::array<int,3>colors={kBlack,kBlue+1,kRed+1};for(int s=0;s<3;++s){if(!sp[s].h||!sp[s].h->Integral())continue;auto h=std::unique_ptr<TH1D>(static_cast<TH1D*>(sp[s].h->Clone()));h->SetDirectory(nullptr);h->Scale(1/h->Integral(0,h->GetNbinsX()+1));h->SetTitle(title.c_str());h->SetLineColor(colors[s]);h->SetLineWidth(2);h->SetMaximum(.22);h->Draw(first?"HIST":"HIST SAME");legend.AddEntry(h.get(),names[s].c_str(),"l");first=false;clones.push_back(std::move(h));}legend.DrawClone();}
void pairedTruth(const fs::path&,const fs::path&,const fs::path&,const std::map<int,mmr::Parameter>&);
