 require(argc==4,"Usage: MuonsCTReview OLD_COLLECTION NEW_COLLECTION OUTPUT_DIR");fs::path old=argv[1],fresh=argv[2],out=argv[3];fs::create_directories(out);gROOT->SetBatch();TH1::AddDirectory(false);gStyle->SetOptStat(0);
