 for(int g=0;g<4;++g){for(int s=0;s<3;++s){auto&h=*global[m][g][s].h;auto&a=global[m][g][s].stats;double total=h.Integral(0,h.GetNbinsX()+1),q16=quantile(h,.16),q50=quantile(h,.5),q84=quantile(h,.84);summary<<condition<<'\t'<<groupName(g)<<'\t'<<names[s]<<'\t'<<a.n<<'\t'<<a.sw<<'\t'<<a.neff()<<'\t'<<a.mean()<<'\t'<<a.error()<<'\t'<<q16<<'\t'<<q50<<'\t'<<q84<<'\t'<<(q84-q16)/2/q50<<'\t'<<(total?h.Integral(0,h.FindFixBin(.5)-1)/total:NaN)<<'\t'<<(total?h.Integral(h.FindFixBin(2),h.GetNbinsX()+1)/total:NaN)<<'\t'<<(total?h.GetBinContent(0)/total:NaN)<<'\t'<<(total?h.GetBinContent(h.GetNbinsX()+1)/total:NaN)<<'\n';auto&e=efficiency[m][g][s];hits<<condition<<'\t'<<groupName(g)<<'\t'<<names[s]<<'\t'<<e.observed.n<<'\t'<<e.observed.sw<<'\t'<<e.observed.events.size()<<'\t'<<e.observed.mean()<<'\t'<<e.observed.error()<<'\t'<<e.response.mean()<<'\t'<<e.response.error()<<'\n';}draw(c,g+1,global[m][g],groupName(g)+";20 C / 2 mm corrected HG ADC / MIP;Probability / bin",clones);}c.SaveAs((out/(condition+"_adc.png")).c_str());c.Clear();
